const CardItem_Map = (mapx,mapy,mlevel) => {

    //스크립트로 api가져오면 window전역객체로 분류.
    // 함수형 컴포넌트에서는 인식 못함 -> 때문에 변수선언.
    
    //console.log(mapx);
    //console.log(mapy);
    //console.log(mlevel);

    const useNaverLoader = () => {
        new window.naver.maps.Map('map',{
          center: new window.naver.maps.LatLng(mapy,mapx),
          zoom: mlevel
        })
      }
      
    useNaverLoader();
    return (
        <div className="cardItemMap">
            
        </div>
    );
}


export default CardItem_Map;
